CREATE TABLE "users" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "role_id" int DEFAULT 2,
  "email" varchar UNIQUE,
  "password" varchar,
  "name" varchar,
  "email_verified_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "remember_token" varchar,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "roles" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "personals" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int,
  "phone_number" varchar,
  "mobile_number" varchar,
  "sex" sex,
  "birth_date" date,
  "religion" religion,
  "passport_number" varchar UNIQUE,
  "passport_expiry_date" date,
  "marital_status" maritalstatus DEFAULT 'single',
  "nationality" varchar,
  "country" varchar,
  "province" varchar,
  "city" varchar,
  "address" TEXT,
  "postal_code" varchar,
  "photo" varchar,
  "blood_type" varchar,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "schools" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int,
  "name" varchar,
  "address" text,
  "country" varchar,
  "province" varchar,
  "city" varchar,
  "state" varchar,
  "zip_code" varchar,
  "phone" varchar,
  "email" varchar,
  "graduation_year" smallint,
  "gpa" decimal(2,2),
  "gpa_max" decimal(2,2),
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "documents" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int,
