  "financial_document" varchar,
  "medical_document" varchar,
  "parental_document" varchar,
  "passport_document" varchar,
  "passport_copy_document" varchar,
  "certificate_document" varchar,
  "transcript_document" varchar,
  "cv_document" varchar,
  "english_certificate_document" varchar,
  "essay_document" varchar,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

